from lib import *
S = SS('v52')
steps = [
    step("先分清角色。集群是 3 个 server 加 2 个 client 模式的 agent(v52a0、v52a1)。gossip 成员表里 5 个成员都是 alive,role 标签为 consul 的 3 个是 server,为 node 的 2 个是 client agent。Raft 的投票成员只有 3 个 server(v52cn0、v52cn1、v52cn2),/v1/status/peers 返回 3 个地址,client agent 不在其中。服务 web 登记在 client agent v52a0 上,从另一个 client agent v52a1 查 catalog 得到 1 条:节点 v52a0、服务 ID web-on-a0、地址 127.0.0.1——服务挂在登记它的那个 agent 的节点上。", t=tl(S(1)), mark=lidx(S(1), 'Raft 投票成员数'), done=lidx(S(1), 'v52a0', 'v52cn0'), b=bars([['gossip 成员', 5, '5(3 server + 2 client)'], ['Raft 投票成员', 3, '3(只有 server)'], ['client agent', 2, '2']], 5, done=[0], mark=[1], cur=[2]), kv=KV([['server', 'role=consul,参与 Raft'], ['client agent', 'role=node,只加入 gossip'], ['服务 web', '挂在登记它的 v52a0 节点上']], ['server'])),
    step("gossip 怎么发现一个节点没了。在 client agent v52a1 上登记服务 gsvc(没有任何健康检查),从 server 0 的视角每 50 ms 查一次。SIGKILL 这个 agent 三次:成员状态不再是 alive 的时间 5.10 / 5.35 / 5.37 s;每一次 serfHealth 变 critical 和服务从 ?passing 消失都与它在同一个采样点(50 ms 内),结束时 catalog 里的 gsvc 仍是 1 个,?passing 是 0 个。在那 5 秒多里服务照样 passing。consul leave 优雅离开:成员状态 0.06 s 就变了,节点 0.25 s 后从 catalog 消失,catalog 里的 gsvc 是 0 个,不经过 critical。", t=tl(S(2)), mark=lidx(S(2), 'SIGKILL'), done=lidx(S(2), 'consul leave'), b=bars([['SIGKILL 第 1 次 s', 5.10, '5.10'], ['SIGKILL 第 2 次 s', 5.35, '5.35'], ['SIGKILL 第 3 次 s', 5.37, '5.37'], ['consul leave:节点消失 s', 0.25, '0.25']], 5.5, mark=[0, 1, 2], done=[3]), kv=KV([['被杀的节点', '5 秒多后 failed,服务 critical,catalog 里还在'], ['优雅离开', '0.25 s 内节点从 catalog 消失'], ['被杀之前', '服务照样 passing']], ['被杀的节点'])),
    step("HTTP 检查的状态流转。同一个后端上挂 2 个检查:default(interval 1 s,timeout 1 s)和 slow(failures_before_critical=3,success_before_passing=2)。刚登记时两个都是 critical,过了 0.29 s 和 0.17 s 才变 passing。后端状态码改变后到目标状态的用时(6 轮,改动落在检查周期的不同位置):200→429,default 0.06~0.99 s,slow 0.42~0.95 s;429→500,default 0.44~1.04 s,slow 2.33~2.96 s;500→200,default 0.18~0.87 s,slow 1.08~1.80 s。429 变 warning 两个都在一个周期内;slow 要连续 3 次失败才变 critical、2 次成功才恢复。Output 字段原样记录原因:500 是 “HTTP GET …: 500 Internal Server Error Output: x”,超时是 “context deadline exceeded (Client.Timeout exceeded while awaiting headers)”,后端停了是 “dial tcp …: connect: connection refused”。", t=tl(S(3)), mark=lidx(S(3), '429→500', 'Output'), done=lidx(S(3), '200→429', '500→200', '刚登记时'), b=bars([['default 429→500 最长 s', 1.04, '1.04'], ['slow 429→500 最长 s', 2.96, '2.96'], ['default 500→200 最长 s', 0.87, '0.87'], ['slow 500→200 最长 s', 1.80, '1.80']], 3.0, done=[0, 2], mark=[1, 3]), kv=KV([['刚登记', 'critical,约 0.3 s 内变 passing'], ['429', 'warning'], ['slow', '3 次失败才 critical,2 次成功才 passing'], ['超时', 'context deadline exceeded …']], ['slow'])),
    step("其他类型的检查。TTL 检查:刚登记是 critical;应用汇报 pass 变 passing;之后不再汇报,3.00 s 后变 critical(TTL 3 s),Output 是 “TTL expired”;汇报 warn 变 warning,汇报 fail 变 critical。TCP 检查:端口监听时 0.79 s 变 passing,关掉端口后 0.53 s 变 critical,Output 是 dial tcp 连接被拒。脚本检查(Args)在默认配置下登记:HTTP 500,响应 “Scripts are disabled on this agent from remote calls; to enable, configure 'enable_script_checks' to true”。", t=tl(S(4)), mark=lidx(S(4), '之后不再汇报', '脚本检查'), done=lidx(S(4), '汇报 pass', 'TCP 检查'), b=bars([['TTL 不汇报到 critical s', 3.00, '3.00(TTL 3 s)'], ['TCP 端口关掉到 critical s', 0.53, '0.53'], ['TCP 监听到 passing s', 0.79, '0.79']], 3.0, mark=[0], done=[1, 2]), kv=KV([['TTL', '不汇报就过期成 critical'], ['TCP', '只看端口通不通'], ['脚本', '默认配置下登记被拒(HTTP 500)']], ['脚本'])),
    step("服务和检查的权威状态在 client agent 本地,再同步给 server。杀掉 3 个 server 中的 2 个(只剩 1 个,没有 leader)。在 client agent 上登记 api 返回 HTTP 200,把 dep 的后端改成返回 500,agent 本地 depc 检查 1.00 s 后变 critical,本地服务列表里有 api-1。经 agent 查 catalog 里的 api:默认读 8 次全部 HTTP 500(rpc error);?stale 读 8 次里 6 次 HTTP 200 但是 0 条,2 次 HTTP 500。查 dep 的 depc 状态(?stale)8 次都是 passing——agent 本地已经是 critical,catalog 还是旧的。把两个 server 拉起来:2.54 s 后可以写入,3.39 s 后 catalog 里出现 api,同一时刻 dep 的检查变成 critical。", t=tl(S(5)), mark=lidx(S(5), 'api(默认)', 'api(?stale)', 'depc 状态'), done=lidx(S(5), 'agent 本地:depc', '登记 api', '把两个 server'), b=bars([['agent 本地 depc 变化 s', 1.00, '1.00(critical)'], ['可以写入 s', 2.54, '2.54'], ['catalog 追上 s', 3.39, '3.39']], 3.5, done=[0], mark=[1, 2]), kv=KV([['server 失联时', 'agent 本地登记、检查照常'], ['catalog', '旧数据:depc=passing ×8'], ['server 回来后', '3.39 s 同步 api 和 dep 状态']], ['catalog'])),
    step("同一个服务三个实例,检查状态不同,各个入口看到什么。tri-1 返回 200(passing),tri-2 返回 429(warning),tri-3 返回 500(critical)。catalog:3 个,不看健康状态。/v1/health/service/tri:3 个,带状态(tri-1 passing、tri-2 warning、tri-3 critical)。?passing:1 个(tri-1),warning 也被去掉。DNS SRV tri.service.consul:2 个(tri-1、tri-2),warning 的实例在,critical 的没有。", t=tl(S(6)), mark=lidx(S(6), '?passing', 'DNS SRV'), done=lidx(S(6), 'catalog(', '/v1/health/service/tri  '), b=bars([['catalog', 3, '3'], ['health', 3, '3(带状态)'], ['?passing', 1, '1'], ['DNS SRV', 2, '2']], 3, done=[0, 1], mark=[2, 3]), kv=KV([['catalog', '全部 3 个'], ['?passing', '只有 passing 的 1 个'], ['DNS', 'passing + warning 共 2 个']], ['DNS'])),
    step("自动注销。4 个服务都指向没人监听的端口,登记后检查马上是 critical。DeregisterCriticalServiceAfter 设为 10s、10s、30s 的三个服务,都在变 critical 后 76.3 s 从 agent 本地消失;设为 90s 的在 106.3 s 消失。设置值小于一分钟时并没有按设置值生效,三个值落在同一个时刻;90s 的比前者晚 30 s。结束时 catalog 里 dereg 的实例数是 0。", t=tl(S(7)), mark=lidx(S(7), 'd10a', 'd10b', 'd30'), done=lidx(S(7), 'd90'), b=bars([['10s 的服务消失 s', 76.3, '76.3'], ['30s 的服务消失 s', 76.3, '76.3'], ['90s 的服务消失 s', 106.3, '106.3']], 110, mark=[0, 1], done=[2]), kv=KV([['10s / 30s', '都约 76 s 后消失'], ['90s', '约 106 s 后消失'], ['登记后立刻', '检查是 critical']], ['10s / 30s'])),
]
A = mkartv('v52', 52, '微服务,注册中心,Consul,gossip,健康检查,真实验证,动画演示',
    '实测 Consul 2.0.4:3 个 server 加 2 个 client agent,Raft 投票成员只有 3 个;SIGKILL 一个 agent 后 5.10 到 5.37 s 才被判为 failed;HTTP 检查 slow 配置(3 次失败 / 2 次成功)从 429 到 500 要 2.33 到 2.96 s;server 失联时 agent 本地照常登记但 catalog 是旧的,恢复后 3.39 s 追上;设 10s 的自动注销实际在 76.3 s 后才发生。',
    'Consul 里 server、client agent、gossip 各管什么?一个节点没了多久能发现?HTTP、TTL、TCP 检查的状态怎么流转,failures_before_critical 有什么用?server 失联时服务注册会怎样?这篇用 3 个 server 加 2 个 client agent 逐项量出来。',
    [('5.10 ~ 5.37 s', 'SIGKILL 一个 client agent 后,gossip 判它 failed(服务变 critical)的用时,三次'), ('2.33 ~ 2.96 s', 'failures_before_critical=3 的 HTTP 检查,从后端返回 500 到变 critical 的用时(默认设置只要 0.44 ~ 1.04 s)'), ('3.39 s', 'server 恢复后 catalog 里出现 agent 本地早已登记的 api,以及 dep 变 critical 的用时')],
    [('角色', '<p>server 参与 Raft,client agent 只加入 gossip;服务挂在登记它的 agent 节点上。</p>'),
     ('gossip 与节点故障', '<p>被杀的节点几秒后才被判为 failed,在那之前服务照样 passing;优雅离开则立刻从 catalog 消失。</p>'),
     ('HTTP 检查的状态流转', '<p>HTTP 检查按 interval 轮询,状态码 429 是 warning;failures_before_critical 和 success_before_passing 决定翻转的速度。</p>'),
     ('TTL、TCP 与脚本检查', '<p>TTL 检查靠应用自己汇报,过期就是 critical;TCP 检查只看端口;脚本检查默认配置下登记被拒。</p>'),
     ('agent 本地状态与同步', '<p>server 失联时 agent 本地照常登记和检查,catalog 返回的是旧数据,server 恢复后再同步。</p>'),
     ('各个入口怎么对待 warning', '<p>catalog 不看健康状态,?passing 去掉 warning,DNS 的应答里有 warning、没有 critical。</p>'),
     ('自动注销', '<p>DeregisterCriticalServiceAfter 设得小于一分钟时实际生效时间比设置值长得多,要按实测的时间来规划。</p>')],
    steps,
    [ENV_V + '。Consul 是 Homebrew 的 2.0.4,3 个 server(-bootstrap-expect=3)加 2 个 client 模式的 agent,全部在 127.0.0.1;后端是本进程里的小 HTTP 服务;DNS 查询用 dnspython;gossip 时间各测了 3 次(SIGKILL),HTTP 检查的状态流转在随机错开的位置上各测了 6 次',
     '没有验证:gossip 失败检测的时间随集群规模和 gossip 参数变化(这里只有 5 个节点、默认参数);WAN gossip 与多数据中心;ACL、Connect、gRPC / Docker / alias 类检查;检查数量很大时 agent 的负载;DNS 的 only_passing 等配置;DeregisterCriticalServiceAfter 为什么在 76 s 而不是 10 s 生效(我印象中官方文档写的最小值是 1 分钟,没有查文档或源码,这里只有测到的数字);?consistent 一致性模式(见第 48 篇)'],
    'Consul 的分工与健康检查')
